\declaretheorem[style=remark,sibling=theorem]{remark}
% Section-qualified hyperref anchors, so that equal numbers in different
% sections (and appendices) get distinct link targets.
\renewcommand{\theHequation}{\theHsection.\arabic{equation}}
\renewcommand{\theHtheorem}{\theHsection.\arabic{theorem}}
\providecommand{\theHproposition}{}\renewcommand{\theHproposition}{\theHsection.\arabic{theorem}}
