\end{tikzpicture}
\caption{Normalised variance at $x=2.56\cdot10^8$ against $\sqrt r$ (filled marks), the snapshot's empirical fits $C+a\sqrt r+br$ (dashed), and the proved constants $C_f$ (open circles at $r=0$).}
\label{fig:ratio}
\end{figure}

\begin{figure}[htbp]
\centering
