  legend pos=outer north east,legend cell align=left,legend style={font=\footnotesize},tick label style={font=\footnotesize},
  yticklabel style={/pgf/number format/fixed,/pgf/number format/precision=3}]
\addplot[blue,mark=*,mark size=1.3pt] table[x=x,y=N]{generated/fig_x_0a.dat};\addlegendentry{$k^2+1$, $r=0.01$}
\addplot[blue,mark=o,mark size=1.3pt,dashed] table[x=x,y=N]{generated/fig_x_0b.dat};\addlegendentry{$k^2+1$, $r=1$}
\addplot[red,mark=square*,mark size=1.3pt] table[x=x,y=N]{generated/fig_x_1a.dat};\addlegendentry{$k^3+2$, $r=0.01$}
\addplot[red,mark=square,mark size=1.3pt,dashed] table[x=x,y=N]{generated/fig_x_1b.dat};\addlegendentry{$k^3+2$, $r=1$}
